# ==========================================
# JOGADOR (HERÓI)
# ==========================================
ENTITY player
TRANSFORM 0.0 0.0 0.0
PHYSICS 0.0 0.0 0.0 0.90
COLLISION -1.0 -1.0 -1.0 1.0 2.0 1.0 0 0
PLAYER_CONTROL
HUD 100.0 2.0 10.0
HEALTH 100.0

# --- Armas do Jogador ---
# TYPE RATE SPEED DMG RANGE HEAT BURST_TOT BURST_RATE SND_ID MDL_ID

ENTITY p_laser_L
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.5 150.0 5.0 500.0 2.0 2 0.1
ATTACHMENT player -1.70 5.50 1.50

ENTITY p_laser_R
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.5 150.0 5.0 500.0 2.0 2 0.1
ATTACHMENT player 1.70 5.50 1.50

ENTITY p_missile_L
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 25.0 1000.0 5.0 20 0.115
ATTACHMENT player -1.70 7.00 1.50

ENTITY p_missile_R
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 25.0 1000.0 5.0 20 0.115
ATTACHMENT player 1.70 7.00 1.50

# Loadout do Player
WEAPON_SLOTS p_laser_L p_laser_R p_missile_L p_missile_R


# ==========================================
# INIMIGO 1: SCOUT (Patrulha Quadrada)
# ==========================================
ENTITY scout1
TRANSFORM 20.0 0.0 70.0
PHYSICS 0.0 0.0 0.0 0.90
# Caixa ajustada manualmente para o Scout (escala 0.5)
COLLISION -1.5 0.0 -1.5 1.5 6.0 1.5 0 0
HEALTH 100.0
RENDER 1 255 255 255 255 
# AI: Sight Range
AI_CONTROL 50.0 10.0
# Patrol: Count P1 P2 P3 P4
AI_PATROL 4 20 0 70 -20 0 70 -20 0 30 20 0 30

# Arma do Scout 1
ENTITY scout1_gun
TRANSFORM 0 0 0
WEAPON WEAPON_LASER_PULSE 1.0 100.0 2.0 300.0 0.0 1 0.0 
ATTACHMENT scout1 0.0 3.0 2.0

WEAPON_SLOTS scout1_gun


# ==========================================
# INIMIGO 2: SCOUT (Patrulha Linha)
# ==========================================
ENTITY scout2
TRANSFORM 15.0 0.0 80.0
PHYSICS 0.0 0.0 0.0 0.90
COLLISION -1.5 0.0 -1.5 1.5 6.0 1.5 0 0
HEALTH 100.0
RENDER 1 255 255 255 255
AI_CONTROL 50.0 10.0
AI_PATROL 2 15 0 80 -15 0 80

ENTITY scout2_gun
TRANSFORM 0 0 0
WEAPON WEAPON_LASER_PULSE 1.0 100.0 2.0 300.0 0.0 1 0.0
ATTACHMENT scout2 0.0 3.0 2.0

WEAPON_SLOTS scout2_gun


# ==========================================
# INIMIGO 3: COMBATENT (Parado/Guarda)
# ==========================================
ENTITY combatent1
TRANSFORM 0.0 0.0 50.0
PHYSICS 0.0 0.0 0.0 0.90
# Combatent é maior (escala 1.0), caixa maior
COLLISION -3.0 0.0 -3.0 3.0 12.0 3.0 0 0
HEALTH 150.0
RENDER 1 255 255 255 255
AI_CONTROL 150.0 100.0
# Sem AI_PATROL, ele fica parado

ENTITY comb1_gun
TRANSFORM 0 0 0
WEAPON WEAPON_LASER_PULSE 0.2 120.0 3.0 100.0 0.0 1 0.0
ATTACHMENT combatent1 0.0 3.0 2.0

WEAPON_SLOTS comb1_gun


# --- CONFIGURAÇÃO DE LOADOUT (Vínculos) ---
# Sintaxe: LINK_WEAPON <Dono> <Slot> <Arma> <Grupo> <AtivoDefault?>

# Lasers no Grupo 0 (Tecla 1), Slot 0 e 1. Ativos (1).
LINK_WEAPON player 0 p_laser_L 0 1
LINK_WEAPON player 1 p_laser_R 0 1

# Mísseis no Grupo 1 (Tecla 2), Slot 2 e 3. Inativos (0) ou Ativos (1).
LINK_WEAPON player 2 p_missile_L 1 0
LINK_WEAPON player 3 p_missile_R 1 0
